const customKey='betaform-custom-holds-v1';
function validateCustom(d){if(!d||!String(d.id).startsWith('custom-')||typeof d.name!=='string'||d.name.length>60||!['Jugs','Edges','Pinches','Slopers','Pockets','Feet','Rails','Macros'].includes(d.family))throw Error('Invalid hold definition');for(const k of ['w','h','d'])if(!Number.isFinite(d[k])||d[k]<.005||d[k]>1.5)throw Error('Hold dimensions are out of range');if(d.outline&&(!Array.isArray(d.outline)||d.outline.length<3||d.outline.length>80||d.outline.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v)||Math.abs(v)>1.01))))throw Error('Invalid outline');if(!Array.isArray(d.bolt)||d.bolt.length!==2||d.bolt.some(v=>!Number.isFinite(v)||Math.abs(v)>1))throw Error('Invalid bolt position');if(!d.outline&&!HOLD_LIBRARY.some(x=>x.shape===d.shape&&!x.outline))throw Error('Unknown base shape');return d;}
try{const stored=JSON.parse(localStorage.getItem(customKey)||'[]');if(Array.isArray(stored))for(const raw of stored.slice(0,60)){try{const d=validateCustom(raw);d.custom=true;if(!byId[d.id]){HOLD_LIBRARY.push(d);byId[d.id]=d;}}catch{}}}catch{}
